import{_ as c,C as r,o as s,c as d,a5 as l,E as i,j as a,a as t,b as A,w as n,a6 as u}from"./chunks/framework.D_J2JZBr.js";const D=JSON.parse('{"title":"半导体器件与新型存储","description":"从自旋电子、宽禁带器件到新型存储，认识上科大的器件研究入口。","frontmatter":{"title":"半导体器件与新型存储","description":"从自旋电子、宽禁带器件到新型存储，认识上科大的器件研究入口。"},"headers":[],"relativePath":"explore-ic/research-directions/devices.md","filePath":"explore-ic/research-directions/devices.md","lastUpdated":1795531638000}'),p={name:"explore-ic/research-directions/devices.md"};function B(f,e,m,b,g,_){const o=r("FacultyList"),E=r("CourseTable"),h=r("Mermaid");return s(),d("div",null,[e[1]||(e[1]=l('<h1 id="半导体器件与新型存储" tabindex="-1">半导体器件与新型存储 <a class="header-anchor" href="#半导体器件与新型存储" aria-label="Permalink to &quot;半导体器件与新型存储&quot;">​</a></h1><h2 id="这个方向在做什么" tabindex="-1">这个方向在做什么 <a class="header-anchor" href="#这个方向在做什么" aria-label="Permalink to &quot;这个方向在做什么&quot;">​</a></h2><p>器件研究回答“用什么物理结构实现开关、存储和信号转换”。传统晶体管依靠电荷输运工作，自旋电子学（Spintronics）还利用电子自旋与磁性状态；宽禁带半导体则为高压、高温、高频场景提供不同于硅的设计空间。新机制不自动等于好芯片，必须把可重复性、工艺兼容性与电路接口一起评估。</p><p>核心研究问题包括：</p><ul><li>如何在电压、速度、保持时间与写入寿命之间权衡存储单元？</li><li>材料界面、缺陷与陷阱如何影响漏电、噪声和动态特性？</li><li>如何利用自旋、磁性或低维结构实现新的功能？</li><li>低温、高场或大功率条件下，已有模型何时失效？</li><li>怎样把单器件的实验结果转化为可集成、可制造的阵列与电路？</li></ul><h2 id="上科大谁在做" tabindex="-1">上科大谁在做 <a class="header-anchor" href="#上科大谁在做" aria-label="Permalink to &quot;上科大谁在做&quot;">​</a></h2><p>上科大相关研究并非只有一条“缩小晶体管”的路线。寇煦丰的公开方向包含微纳电子器件与电路、自旋电子学、拓扑量子体系应用和低温电子学；杨雨梦关注磁存储与磁传感器，祝智峰关注基于自旋电子的磁存储和类脑计算。三者都涉及磁性与电子器件，但具体研究问题不能简单互换。</p><p>另一条线是器件与应用系统的连接：邹新波研究第三代半导体功率器件、GaN 基微波与毫米波器件及陷阱物性；廖立杨关注面向量子信息、射频器件和芯片电源管理的自旋电子学混合系统。封松林的公开方向包括微系统、量子器件与低维半导体；陈佰乐的光电探测与 III-V 族器件则连接到 <a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/research-directions/photonics">光电子方向</a>。下列卡片按站内方向标签展示，不表示每位老师都研究本页所有主题。</p>',8)),i(o,{dir:"devices"}),e[2]||(e[2]=a("h2",{id:"相关上科大课程",tabindex:"-1"},[t("相关上科大课程 "),a("a",{class:"header-anchor",href:"#相关上科大课程","aria-label":'Permalink to "相关上科大课程"'},"​")],-1)),e[3]||(e[3]=a("p",null,"可从 EE120 建立器件基础，再结合兴趣选择器件物理、工艺或自旋电子学；选课资格与正式先修要求以当学期大纲为准。",-1)),i(E,{codes:"EE120,EE220,EE2211,EE224A,EE237,EE291C"}),e[4]||(e[4]=a("h2",{id:"知识前置",tabindex:"-1"},[t("知识前置 "),a("a",{class:"header-anchor",href:"#知识前置","aria-label":'Permalink to "知识前置"'},"​")],-1)),e[5]||(e[5]=a("p",null,"下图是建议学习路径，不替代教务系统的先修关系；物理、微积分、线性代数应贯穿学习过程。",-1)),(s(),A(u,null,{default:n(()=>[i(h,{id:"mermaid-64",class:"mermaid",graph:"graph%20TD%0A%20%20A%5B%22%E6%99%AE%E9%80%9A%E7%89%A9%E7%90%86%E4%B8%8E%E6%95%B0%E5%AD%A6%E5%9F%BA%E7%A1%80%22%5D%20--%3E%20B%5B%22EE130%20%E7%94%B5%E7%A3%81%E5%AD%A6%22%5D%0A%20%20A%20--%3E%20C%5B%22EE111%20%E7%94%B5%E8%B7%AF%E5%9F%BA%E7%A1%80%22%5D%0A%20%20B%20--%3E%20D%5B%22EE120%20%E5%8D%8A%E5%AF%BC%E4%BD%93%E5%99%A8%E4%BB%B6%E5%9F%BA%E7%A1%80%22%5D%0A%20%20D%20--%3E%20E%5B%22EE220%20%E5%8D%8A%E5%AF%BC%E4%BD%93%E5%99%A8%E4%BB%B6%E7%89%A9%E7%90%86%22%5D%0A%20%20D%20--%3E%20F%5B%22EE237%20%E8%87%AA%E6%97%8B%E7%94%B5%E5%AD%90%E5%AD%A6%22%5D%0A%20%20A%20--%3E%20G%5B%22EE224A%20%E5%BE%AE%E7%BA%B3%E5%99%A8%E4%BB%B6%E5%B7%A5%E8%89%BA%E5%9F%BA%E7%A1%80%22%5D%0A%20%20C%20--%3E%20H%5B%22EE2211%20%E5%BE%AE%E7%94%B5%E5%AD%90%E5%99%A8%E4%BB%B6%22%5D%0A%20%20E%20--%3E%20I%5B%22%E5%99%A8%E4%BB%B6%E4%B8%8E%E6%96%B0%E5%9E%8B%E5%AD%98%E5%82%A8%E7%A0%94%E7%A9%B6%22%5D%0A%20%20F%20--%3E%20I%0A%20%20G%20--%3E%20I%0A%20%20H%20--%3E%20I%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=l('<h2 id="领域地图" tabindex="-1">领域地图 <a class="header-anchor" href="#领域地图" aria-label="Permalink to &quot;领域地图&quot;">​</a></h2><ul><li><strong>研究机构</strong>：可从 Berkeley、Stanford 的电子器件研究、清华与北大的微电子相关团队、中国科学院微电子所和上海微系统所了解不同材料及器件路线。选择具体课题组时，应查看近期论文而非只看机构名。</li><li><strong>产业参照</strong>：台积电、Intel、三星的制造与存储技术，Infineon 的功率半导体，有助于理解工艺平台与器件指标之间的联系；这不是上科大合作名单。</li><li><strong>会议与期刊</strong>：IEDM、VLSI Symposium 的器件技术方向，以及 IEEE Transactions on Electron Devices（TED）、IEEE Electron Device Letters（EDL）。自旋与新材料工作也常见于 Nature Electronics、Physical Review 系列等期刊。</li></ul><p>读论文时先找测试结构、偏置条件、温度和统计样本，再看亮眼指标。单次测到的低能耗，不等于可量产阵列的系统能耗。</p><h2 id="入门资源" tabindex="-1">入门资源 <a class="header-anchor" href="#入门资源" aria-label="Permalink to &quot;入门资源&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/learning/devices-and-process/resources">器件自学路线</a> 与 <a href="/shanghaitech-ic-wiki-dev.github.io/learning/devices-and-process/">器件学习地图</a>：安排物理、器件模型和工艺知识。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/explore-ic/devices-process">器件与工艺基础</a>：先掌握常用工艺与术语。</li><li><a href="https://nanohub.org/" target="_blank" rel="noreferrer">nanoHUB</a>：器件教学、模型与仿真资源。</li><li><a href="https://eds.ieee.org/" target="_blank" rel="noreferrer">IEEE Electron Devices Society</a>：查找器件领域会议、期刊与教育活动。</li></ul><p>一个合适的起步练习是选定一种器件，画出结构、能带和等效电路，再解释一组公开的电流—电压曲线；不要在尚未理解模型适用范围时直接比较不同论文的数字。</p><h2 id="社区经验征集" tabindex="-1">社区经验征集 <a class="header-anchor" href="#社区经验征集" aria-label="Permalink to &quot;社区经验征集&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">征集</p><p>欢迎该方向课题组同学通过 <a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing">参与共建</a> 补充“组里在做什么”、公开实验技能与进组准备建议；请区分已公开研究和未公开结果，不提交个人评价或隐私。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://sist.shanghaitech.edu.cn/kouxf/main.htm" target="_blank" rel="noreferrer">寇煦丰学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/yangym1/main.htm" target="_blank" rel="noreferrer">杨雨梦学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/zhuzhf/main.htm" target="_blank" rel="noreferrer">祝智峰学院主页</a>。</li><li><a href="https://sist.shanghaitech.edu.cn/zouxb/main.htm" target="_blank" rel="noreferrer">邹新波学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/lly1/main.htm" target="_blank" rel="noreferrer">廖立杨学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/fengsl/main.htm" target="_blank" rel="noreferrer">封松林学院主页</a>。</li><li><a href="https://sist.shanghaitech.edu.cn/_upload/article/files/d0/82/218152ad4bd29c54d8a89d0e6be7/2cba84cd-d335-4a72-8f17-68175bed8e69.pdf" target="_blank" rel="noreferrer">后摩尔中心介绍材料</a>：约 2024 年方向材料。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">2026–2027 学年 SIST 开课计划</a>：开课、教师与课程要求以最新公布为准。</li></ul>',10))])}const v=c(p,[["render",B]]);export{D as __pageData,v as default};
